$$ $$
= F _ {1} (x _ {\mathrm{s}}, x) x ^ {- \alpha} e ^ {- x} \int_ {0} ^ {\infty} t ^ {\alpha - 2} (x + t) ^ {\alpha + 2} e ^ {- t} d t.
